#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# RP-1036 (ADR 0026): the accounts and keys only the product owner can create
# for dev and UAT on Vercel. Every secret goes to the GitHub environment `uat`
# and nowhere else; only public values (bucket names, addresses) are also kept
# in .env.uat (git-ignored) so a re-run offers them back.
#
# Run from the repo root in Git Bash:  bash scripts/setup-uat-accounts.sh

TOTAL_STAGES=9
ENV_FILE=".env.uat"
REPO="Rabaed/rabaedV2.0"
GH_ENV="uat"

# Wizard helpers for the `uat` environment (the library's set_secret/set_var
# write repo-wide; these write to the environment only).
uat_secret() {
  local name="$1" value="$2"
  if [[ -z "$value" ]]; then SKIPPED+=("secret $name (empty)"); warn "nothing entered for $name; skipped"; return; fi
  if printf '%s' "$value" | gh secret set "$name" --env "$GH_ENV" --repo "$REPO" >/dev/null 2>&1; then
    WRITTEN_SECRET+=("$name"); printf '  %s✓ set%s secret %s (environment %s)\n' "$GREEN" "$RESET" "$name" "$GH_ENV"
  else
    SKIPPED+=("secret $name: gh secret set $name --env $GH_ENV --repo $REPO"); warn "could not set $name"
  fi
}
uat_var() {
  local name="$1" value="$2"
  if gh variable set "$name" --env "$GH_ENV" --repo "$REPO" --body "$value" >/dev/null 2>&1; then
    printf '  %s✓ set%s variable %s (environment %s)\n' "$GREEN" "$RESET" "$name" "$GH_ENV"
  else
    SKIPPED+=("variable $name: gh variable set $name --env $GH_ENV --repo $REPO"); warn "could not set $name"
  fi
}
# uat_has_secret NAME: true when the environment already holds it.
uat_has_secret() { gh secret list --env "$GH_ENV" --repo "$REPO" 2>/dev/null | cut -f1 | grep -qx "$1"; }
# s3_call METHOD URL KEY SECRET [FILE]: a signed R2 (S3 API) request; prints the HTTP status.
s3_call() {
  local method="$1" url="$2" key="$3" secret="$4" file="${5:-}" args=()
  [[ -n "$file" ]] && args=(--data-binary "@$file")
  curl -s -o /dev/null -w '%{http_code}' -X "$method" --aws-sigv4 "aws:amz:auto:s3" --user "$key:$secret" "${args[@]}" "$url"
}

banner "Rabaed dev & UAT accounts (RP-1036)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "GitHub: the uat environment"
say "Every key from here on is saved in GitHub's environment \"uat\" on $REPO,"
say "never in the repo and never in a chat. First, check gh is signed in."
if ! command -v gh >/dev/null 2>&1 || ! gh auth status >/dev/null 2>&1; then
  warn "gh is missing or signed out. Run: gh auth login   then run this wizard again."
  exit 1
fi
if gh api -X PUT "repos/$REPO/environments/$GH_ENV" >/dev/null 2>&1; then
  printf '  %s✓ environment%s %s is ready\n' "$GREEN" "$RESET" "$GH_ENV"
else
  warn "could not create the environment (you need admin on $REPO)."; exit 1
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Vercel: Team ID and deploy token"
say "Your Rabaed team is already on Pro. Do NOT create a project: an agent makes"
say "the three projects (web, api, admin) later, in RP-1038."
open_url "https://vercel.com/teams"
step "Pick the Rabaed team → Settings → General → copy \"Team ID\" (starts team_)."
ask VERCEL_ORG_ID "Paste the Team ID:"
open_url "https://vercel.com/account/settings/tokens"
step "Create Token → name: rabaed-uat-deploy → Scope: Rabaed → an expiry you like → Create."
step "Copy the token (shown once)."
ask_secret VERCEL_TOKEN "Paste the token (hidden):"
code=$(curl -s -o /dev/null -w '%{http_code}' -H "Authorization: Bearer $VERCEL_TOKEN" "https://api.vercel.com/v2/teams/$VERCEL_ORG_ID")
if [[ "$code" == "200" ]]; then printf '  %s✓ token reaches the team%s\n' "$GREEN" "$RESET"; else warn "Vercel answered $code: check the Team ID and the token's scope, then re-run."; fi
write_env VERCEL_ORG_ID "$VERCEL_ORG_ID"
uat_var VERCEL_ORG_ID "$VERCEL_ORG_ID"
uat_secret VERCEL_TOKEN "$VERCEL_TOKEN"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Supabase: the project"
open_url "https://supabase.com/dashboard/new"
step "Organization: yours. Name: rabaed-uat."
step "Database password: click Generate, then copy it somewhere safe for the next stage."
step "Region: Central EU (Frankfurt). Plan: Free."
step "If the form shows a \"Data API\" option, turn it OFF. Create the project."
step "When it's ready: Project Settings → Data API → turn \"Enable Data API\" OFF and save."
note "Why: the Data API would be a second door to the tables, past our visibility rules."
note "We use Supabase as plain Postgres only: no Supabase Auth, no Storage, no anon keys."
until confirm "Is the project created in Frankfurt with the Data API OFF?"; do say "Finish it, then answer y."; done

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Supabase: the connection string"
step "In the project, click \"Connect\" (top bar) → \"Session pooler\" → copy the URI."
note "Session pooler, not Direct: GitHub's runners can't reach the IPv6-only direct address,"
note "and migrations need a session (they take a session lock)."
step "In the copied text, replace [YOUR-PASSWORD] with the database password from stage 3."
ask_secret DATABASE_SUPERUSER_URL "Paste the full URI with the password (hidden):"
if [[ "$DATABASE_SUPERUSER_URL" =~ ^postgres(ql)?://postgres\.([a-z0-9]+):[^@]+@([^:/]+):5432/ ]] && [[ "$DATABASE_SUPERUSER_URL" != *"YOUR-PASSWORD"* ]]; then
  SUPABASE_PROJECT_REF="${BASH_REMATCH[2]}"; DATABASE_POOLER_HOST="${BASH_REMATCH[3]}"
  printf '  %s✓ session pooler URI%s (project %s, host %s)\n' "$GREEN" "$RESET" "$SUPABASE_PROJECT_REF" "$DATABASE_POOLER_HOST"
  write_env SUPABASE_PROJECT_REF "$SUPABASE_PROJECT_REF"
  write_env DATABASE_POOLER_HOST "$DATABASE_POOLER_HOST"
  uat_var SUPABASE_PROJECT_REF "$SUPABASE_PROJECT_REF"
  uat_var DATABASE_POOLER_HOST "$DATABASE_POOLER_HOST"
  uat_secret DATABASE_SUPERUSER_URL "$DATABASE_SUPERUSER_URL"
else
  warn "That doesn't look like the session pooler URI (postgresql://postgres.<project>:<password>@<host>:5432/postgres)."
  SKIPPED+=("DATABASE_SUPERUSER_URL: re-run and paste the Session pooler URI")
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Generated passwords"
say "Rabaed's own database roles get random passwords; the bootstrap (RP-1037)"
say "creates the roles with them. Nobody needs to know them. Same for the cron secret."
for name in DATABASE_MIGRATOR_PASSWORD DATABASE_APP_PASSWORD DATABASE_ADMIN_PASSWORD CRON_SECRET; do
  if uat_has_secret "$name" && ! confirm "$name already exists. Replace it (only before RP-1037 has run)?"; then
    note "kept $name"; continue
  fi
  uat_secret "$name" "$(openssl rand -hex 32)"
done
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare R2: two buckets and the fonts"
open_url "https://dash.cloudflare.com/?to=/:account/r2/overview"
step "If asked, enable R2 (it needs a payment method; this use stays in the free tier)."
step "Create bucket → name rabaed-uat-files → Location: Automatic, hint Western Europe → Create."
step "Create bucket → name rabaed-uat-build-assets → same location → Create."
step "Leave both PRIVATE: no public access, no custom domain."
step "On your computer, make a folder fonts/thmanyah/ holding the five thmanyahsans-*.woff2 files."
step "Open rabaed-uat-build-assets → Objects → Upload → drag the whole \"fonts\" folder."
note "The result must be fonts/thmanyah/thmanyahsans-regular.woff2 and so on. Stage 7 checks it."
step "Open either bucket → Settings → copy the \"S3 API\" address."
ask FILE_STORE_ENDPOINT "Paste the S3 API address:"
FILE_STORE_ENDPOINT="${FILE_STORE_ENDPOINT%/}"
FILE_STORE_ENDPOINT="${FILE_STORE_ENDPOINT%/rabaed-uat-files}"
FILE_STORE_ENDPOINT="${FILE_STORE_ENDPOINT%/rabaed-uat-build-assets}"
PROJECT_FILES_BUCKET="rabaed-uat-files"; BUILD_ASSETS_BUCKET="rabaed-uat-build-assets"
write_env FILE_STORE_ENDPOINT "$FILE_STORE_ENDPOINT"
write_env PROJECT_FILES_BUCKET "$PROJECT_FILES_BUCKET"
write_env BUILD_ASSETS_BUCKET "$BUILD_ASSETS_BUCKET"
uat_var FILE_STORE_ENDPOINT "$FILE_STORE_ENDPOINT"
uat_var PROJECT_FILES_BUCKET "$PROJECT_FILES_BUCKET"
uat_var BUILD_ASSETS_BUCKET "$BUILD_ASSETS_BUCKET"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare R2: two keys"
open_url "https://dash.cloudflare.com/?to=/:account/r2/api-tokens"
step "Create API token → name rabaed-uat-files → Permissions: Object Read & Write"
step "  → Specify bucket(s): rabaed-uat-files only → Create. Copy both keys below."
ask_secret FILE_STORE_ACCESS_KEY_ID "Access Key ID (hidden):"
ask_secret FILE_STORE_SECRET_ACCESS_KEY "Secret Access Key (hidden):"
probe=$(mktemp); printf 'rabaed wizard probe' > "$probe"
put=$(s3_call PUT "$FILE_STORE_ENDPOINT/$PROJECT_FILES_BUCKET/wizard-probe.txt" "$FILE_STORE_ACCESS_KEY_ID" "$FILE_STORE_SECRET_ACCESS_KEY" "$probe")
del=$(s3_call DELETE "$FILE_STORE_ENDPOINT/$PROJECT_FILES_BUCKET/wizard-probe.txt" "$FILE_STORE_ACCESS_KEY_ID" "$FILE_STORE_SECRET_ACCESS_KEY")
rm -f "$probe"
if [[ "$put" == "200" && "$del" == "204" ]]; then printf '  %s✓ files key can write and delete%s\n' "$GREEN" "$RESET"; else warn "files key test: upload $put, delete $del (expected 200, 204). Check the token's bucket and permission."; fi
uat_secret FILE_STORE_ACCESS_KEY_ID "$FILE_STORE_ACCESS_KEY_ID"
uat_secret FILE_STORE_SECRET_ACCESS_KEY "$FILE_STORE_SECRET_ACCESS_KEY"
step "Create API token → name rabaed-uat-fonts → Permissions: Object Read only"
step "  → Specify bucket(s): rabaed-uat-build-assets only → Create. Copy both keys below."
ask_secret FONTS_ACCESS_KEY_ID "Access Key ID (hidden):"
ask_secret FONTS_SECRET_ACCESS_KEY "Secret Access Key (hidden):"
listing=$(curl -s --aws-sigv4 "aws:amz:auto:s3" --user "$FONTS_ACCESS_KEY_ID:$FONTS_SECRET_ACCESS_KEY" "$FILE_STORE_ENDPOINT/$BUILD_ASSETS_BUCKET?list-type=2&prefix=fonts/thmanyah/")
faces=$(printf '%s' "$listing" | grep -oiE 'fonts/thmanyah/thmanyahsans-(light|regular|medium|bold|black)\.woff2' | sort -u | wc -l | tr -d ' ')
if [[ "$faces" -ge 1 ]]; then printf '  %s✓ fonts key reads %s Thmanyah file(s)%s\n' "$GREEN" "$faces" "$RESET"; else warn "the fonts key found no fonts/thmanyah/thmanyahsans-*.woff2: check the upload path and the token."; SKIPPED+=("Thmanyah fonts at fonts/thmanyah/ in $BUILD_ASSETS_BUCKET"); fi
uat_secret FONTS_ACCESS_KEY_ID "$FONTS_ACCESS_KEY_ID"
uat_secret FONTS_SECRET_ACCESS_KEY "$FONTS_SECRET_ACCESS_KEY"
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "SendGrid: a send-only key"
open_url "https://app.sendgrid.com/settings/api_keys"
step "Create API Key → name rabaed-uat → Restricted Access → Mail Send: Full Access;"
step "  everything else No Access → Create & View → copy (shown once)."
ask_secret SENDGRID_API_KEY "Paste the API key (hidden):"
scopes=$(curl -s -H "Authorization: Bearer $SENDGRID_API_KEY" "https://api.sendgrid.com/v3/scopes")
if [[ "$scopes" == *'"mail.send"'* ]]; then
  extra=$(printf '%s' "$scopes" | grep -oE '"[a-z_.]+"' | tr -d '"' | grep -vxE 'scopes|mail\.send|sender_verification_eligible|2fa_required|2fa_exempt' | tr '\n' ' ')
  printf '  %s✓ key can send mail%s\n' "$GREEN" "$RESET"
  [[ -n "$extra" ]] && warn "the key also holds: $extra (only Mail Send was meant; consider remaking it)"
else
  warn "SendGrid didn't confirm mail.send for this key; check it and re-run."
fi
uat_secret SENDGRID_API_KEY "$SENDGRID_API_KEY"
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "SendGrid: tracking off, and the sender"
open_url "https://app.sendgrid.com/settings/tracking"
step "Open Tracking → OFF.  Click Tracking → OFF.  (Leave the others off too.)"
note "Click tracking would pass our one-time invitation and reset links through SendGrid."
until confirm "Are open and click tracking both OFF?"; do say "Turn them off, then answer y."; done
say "The From address must be on the domain you authenticated in SendGrid."
ask MAIL_FROM "From address (e.g. no-reply@yourdomain):"
write_env MAIL_FROM "$MAIL_FROM"
uat_var MAIL_FROM "$MAIL_FROM"
pause "Done. Press Enter for the summary."

finish
say "Next: tell Claude that RP-1036 is done; the Supabase test (RP-1037) starts from here."
say "The Records container (Railway, Fly or a Vercel container) is decided separately."
